diff --git a/tfjs-backend-wasm/src/index_test.ts b/tfjs-backend-wasm/src/index_test.ts
index ce0ef4f61..cb1ada11d 100644
--- a/tfjs-backend-wasm/src/index_test.ts
+++ b/tfjs-backend-wasm/src/index_test.ts
@@ -230,3 +230,27 @@ describeWithFlags('wasm init', BROWSER_ENVS, () => {
         .toThrowError(/The WASM backend was already initialized. Make sure/);
   });
 });
+
+describe('wasm pre.js', () => {
+  it('works if process variable is undefined', async () => {
+    tf.engine().reset();
+
+    const savedProcess = process;
+    // This test is not perfect since checks like `if (process)` will not throw
+    // errors if process is set to undefined, however, process can not be
+    // `delete`d due to strict mode.
+
+    process = undefined;
+
+    try {
+      await tf.setBackend('wasm');
+    } catch (e) {
+      fail(e);
+    } finally {
+      process = savedProcess;
+    }
+
+    tf.engine().disposeVariables();
+    tf.engine().reset();
+  });
+});
